'use strict';

// MODULES //

import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import clipUpperIndex from '@stdlib/ndarray-base-clip-upper-index';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-slast-index-equal';


// MAIN //

/**
* Returns the index of the last element in a one-dimensional single-precision floating-point ndarray equal to a corresponding element in another one-dimensional single-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* -   When comparing elements, the function checks for equality using the strict equality operator `===`. As a consequence, `NaN` values are considered distinct, and `-0` and `+0` are considered the same.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* import Float32Vector from '@stdlib/ndarray-vector-float32';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = new Float32Vector( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Float32Vector( [ 0.0, 0.0, 3.0, 0.0 ] );
*
* var fromIndex = scalar2ndarray( 3, {
*     'dtype': 'generic'
* });
*
* var idx = slastIndexEqual( [ x, y, fromIndex ] );
* // returns 2
*/
function slastIndexEqual( arrays ) {
	var fromIndex;
	var N;
	var x;
	var y;

	x = arrays[ 0 ];
	y = arrays[ 1 ];
	fromIndex = ndarraylike2scalar( arrays[ 2 ] );

	N = numelDimension( x, 0 );
	fromIndex = clipUpperIndex( fromIndex, ( fromIndex < 0 ) ? N : N-1 );
	if ( fromIndex < 0 ) {
		return -1;
	}
	return strided( fromIndex+1, getData( x ), getStride( x, 0 ), getOffset( x ), getData( y ), getStride( y, 0 ), getOffset( y ) ); // eslint-disable-line max-len
}


// EXPORTS //

export default slastIndexEqual;
